INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Browsers für Datenschutz entscheidend?', 2, '[{"text": "Privatsphäreneinstellungen", "correct": true, "because": "Schützt persönliche Daten"}, {"text": "Design der Oberfläche", "correct": false, "because": "Kein Einfluss auf Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Browser ohne Add-On-Unterstützung für den Alltag geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Add-Ons erweitern Funktionalität"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Nutzung ohne Erweiterungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Browsers wichtig?', 5, '[{"text": "Geschwindigkeit beim Laden", "correct": true, "because": "Bestimmt Benutzererfahrung"}, {"text": "Kompatibilität mit Webstandards", "correct": true, "because": "Sichert Darstellung"}, {"text": "Farbe des Icons", "correct": false, "because": "Kein Einfluss auf Leistung"}, {"text": "Speicherverbrauch", "correct": true, "because": "Beeinflusst Systemlast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Browser richtig? a) Alle Browser unterstützen HTML5. b) Ein Browser kann ohne Internet genutzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Ältere Browser nicht immer"}, {"text": "Nur b) stimmt", "correct": true, "because": "Lokale Dateien können geöffnet werden"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist nicht universell"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Browsers für ein Unternehmen ignorieren?', 2, '[{"text": "Sicherheitsfunktionen", "correct": false, "because": "Wichtig für Datenschutz"}, {"text": "Optische Gestaltung", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Erweiterbarkeit", "correct": false, "because": "Relevant für Anpassung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Browsers für sicheres Surfen entscheidend?', 2, '[{"text": "Sicherheitsfunktionen", "correct": true, "because": "Schutz vor Malware und Phishing"}, {"text": "Design der Oberfläche", "correct": false, "because": "Kein Einfluss auf Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Browser mit mehr Erweiterungen immer besser?', 1, '[{"text": "Nein", "correct": true, "because": "Zu viele können die Leistung beeinträchtigen"}, {"text": "Ja", "correct": false, "because": "Qualität zählt mehr als Quantität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Leistung eines Browsers wichtig?', 5, '[{"text": "Geschwindigkeit beim Laden", "correct": true, "because": "Verbessert Nutzererlebnis"}, {"text": "Unterstützung moderner Standards", "correct": true, "because": "Für aktuelle Webseiten nötig"}, {"text": "Farbe des Icons", "correct": false, "because": "Kein Einfluss auf Funktion"}, {"text": "Speicherverbrauch", "correct": true, "because": "Beeinflusst Systemlast"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Browser richtig? a) Alle Browser unterstützen dieselben Webstandards. b) Ein Browser kann ohne Updates sicher bleiben.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Standards variieren leicht"}, {"text": "Beides stimmt", "correct": false, "because": "Updates sind für Sicherheit nötig"}, {"text": "Nur b) stimmt", "correct": false, "because": "Standards unterscheiden sich"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist nicht korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Browsers für einfaches Surfen ignorieren?', 2, '[{"text": "Entwicklerwerkzeuge", "correct": true, "because": "Nur für Programmierer relevant"}, {"text": "Geschwindigkeit", "correct": false, "because": "Wichtig für Nutzung"}, {"text": "Sicherheitsupdates", "correct": false, "because": "Essenziell für Schutz"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Browsers für schnelles Surfen entscheidend?', 2, '[{"text": "Ladegeschwindigkeit", "correct": true, "because": "Bestimmt die Reaktionszeit"}, {"text": "Farbe des Icons", "correct": false, "because": "Kein Einfluss auf Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Browser ohne JavaScript-Unterstützung für moderne Webseiten geeignet?', 1, '[{"text": "Nein", "correct": true, "because": "Viele Seiten benötigen JavaScript"}, {"text": "Ja", "correct": false, "because": "Eingeschränkte Funktionalität"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften sind für die Sicherheit eines Browsers wichtig?', 5, '[{"text": "Regelmäßige Updates", "correct": true, "because": "Schließt Sicherheitslücken"}, {"text": "Phishing-Schutz", "correct": true, "because": "Verhindert Betrug"}, {"text": "Anzahl der Themes", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Inkognito-Modus", "correct": true, "because": "Schützt Privatsphäre"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Browser richtig? a) Alle Browser unterstützen dieselben Erweiterungen. b) Browser können ohne Internet genutzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Erweiterungen sind browserspezifisch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Lokale Dateien können angezeigt werden"}, {"text": "Beides stimmt", "correct": false, "because": "Aussage a) ist falsch"}, {"text": "Beides falsch", "correct": false, "because": "Aussage b) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Bewertung eines Browsers für den Alltag ignorieren?', 2, '[{"text": "Speicherverbrauch", "correct": false, "because": "Beeinflusst die Systemleistung"}, {"text": "Farbe der Oberfläche", "correct": true, "because": "Kein Einfluss auf Funktion"}, {"text": "Kompatibilität", "correct": false, "because": "Entscheidend für Webseiten"}]');
